/**
 * Returns the standard copyright string used in our games.
 *
 * @param {string} gameName - The game's friendly name
 * @param {number} releaseYear - The year it was first released
 *
 * * @example
 * getCopyrightString('Nevada', 2021);
 */
export function getCopyrightString(gameName, releaseYear) {
    var currentYear = new Date().getFullYear();
    return "".concat(gameName, " \u00A9 tombola Ltd. ").concat(currentYear > releaseYear ? "".concat(releaseYear, " - ").concat(currentYear) : releaseYear);
}
